{
  "rules": [
    {
      "category": "just_cause_eviction",
      "title": "Just Cause Eviction Protections",
      "requirement": "After a tenant has continuously and lawfully occupied residential property for 30 days, a landlord cannot terminate the tenancy without stated at-fault or no-fault just cause.",
      "requirement_es": "Después de que un inquilino haya ocupado continua y legalmente una propiedad residencial durante 30 días, el arrendador no puede rescindir el contrato de alquiler sin una causa justificada culpable o no culpable debidamente indicada.",
      "key_value": null,
      "coverage_conditions": {
        "type": "AND",
        "clauses": [
          {
            "field": "tenancy_length_months",
            "operator": ">=",
            "value": 1,
            "note": "After a Tenant has continuously and lawfully occupied a Residential Real Property for thirty (30) days"
          }
        ]
      },
      "exemptions": [
        {
          "description": "Transient and tourist hotel occupancy as defined in Civil Code § 1940(b)",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Housing accommodations in nonprofit hospital, religious facility, extended care, licensed elderly care, or adult residential facility",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Dormitories owned and operated by higher education or K-12 school",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Housing accommodations where tenant shares bathroom or kitchen facilities with owner maintaining principal residence",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_occupied",
                "operator": "==",
                "value": true
              }
            ]
          }
        },
        {
          "description": "Single-family owner-occupied residences renting no more than two units or bedrooms (including ADU/JADU)",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "single_family"
              },
              {
                "field": "owner_occupied",
                "operator": "==",
                "value": true
              }
            ]
          }
        },
        {
          "description": "Owner-occupied duplex where owner occupied a unit at the start and continues in occupancy",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "duplex"
              },
              {
                "field": "owner_occupied",
                "operator": "==",
                "value": true
              }
            ]
          }
        },
        {
          "description": "Housing issued a certificate of occupancy within the previous 15 years",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "building_age_years",
                "operator": "<",
                "value": 15
              }
            ]
          }
        },
        {
          "description": "Separately alienable residential real property where owner is not a REIT, corporation, or corporate-member LLC, and provided statutory exemption notice",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "in",
                "value": [
                  "single_family",
                  "condominium"
                ]
              },
              {
                "field": "owner_type",
                "operator": "not_in",
                "value": [
                  "reit",
                  "corporation"
                ]
              }
            ]
          }
        },
        {
          "description": "Deed-restricted affordable housing or government subsidized housing",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "rent_subsidized",
                "operator": "==",
                "value": true
              }
            ]
          }
        }
      ],
      "effective_date": "2022-10-18",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "yields_to",
        "target_scope": "state",
        "source_language": "The provisions of this section related to the termination of Tenants shall not apply to Mobilehomes or Mobilehome Spaces in Mobilehome Parks subject to the termination provisions of the Mobilehome Residency Law, Civil Code section 798.56, as applicable."
      },
      "penalty": "Failure to strictly comply renders the notice of termination void; affirmative defense in unlawful detainer; landlord liable in civil action for wrongful eviction including costs and reasonable attorneys' fees; administrative citations, infractions, or misdemeanors.",
      "source_citation": "Santa Ana Mun. Code § 8-3120(a)",
      "quote": {
        "chunk": "c54",
        "start_words": "After a Tenant has continuously and lawfully occupied",
        "end_words": "Civil Code section 798.56, as applicable."
      },
      "confidence": 0.98
    },
    {
      "category": "just_cause_eviction",
      "title": "No-Fault Eviction Relocation Assistance or Rent Waiver",
      "requirement": "If terminating a tenancy for no-fault just cause, the landlord must provide direct relocation assistance or waive rent for the final 3 months, equal to 3 months of the tenant's rent.",
      "requirement_es": "Si se rescinde un contrato de alquiler por una causa justificada no culpable, el propietario debe proporcionar asistencia directa de reubicación o condonar el alquiler durante los últimos 3 meses, por un monto equivalente a 3 meses del alquiler del inquilino.",
      "key_value": {
        "label": "relocation assistance or rent waiver",
        "value": "3 months of rent"
      },
      "coverage_conditions": {
        "type": "AND",
        "clauses": [
          {
            "field": "tenancy_length_months",
            "operator": ">=",
            "value": 1,
            "note": "Tenancy for which just cause is required"
          }
        ]
      },
      "exemptions": [
        {
          "description": "Tenant found at fault by a government agency or court for conditions triggering an order or need to vacate",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Properties exempt from just cause under section 8-3120(e)",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "building_age_years",
                "operator": "<",
                "value": 15
              }
            ]
          }
        }
      ],
      "effective_date": "2022-10-18",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": "The relocation assistance or Rent waiver required by this section shall be credited against any other relocation assistance required by any other law."
      },
      "penalty": "Failure to strictly comply renders the notice of termination void.",
      "source_citation": "Santa Ana Mun. Code § 8-3120(d)",
      "quote": {
        "chunk": "c170",
        "start_words": "The amount of relocation assistance or Rent waiver",
        "end_words": "fifteen (15) calendar days of service of the notice."
      },
      "confidence": 0.98
    },
    {
      "category": "rent_increase_limit",
      "title": "Annual Allowable Rent Increase Cap",
      "requirement": "Landlords may not increase rent on residential real property or mobilehome spaces by more than 3% or 80% of the change in the Consumer Price Index (whichever is less) and may not impose more than one rent increase in any 12-month period. If the CPI change is negative, no rent increase is permitted.",
      "requirement_es": "Los arrendadores no pueden aumentar el alquiler de bienes raíces residenciales o espacios de casas móviles en más del 3% o el 80% del cambio en el Índice de Precios al Consumidor (lo que sea menor) y no pueden imponer más de un aumento en cualquier período de 12 meses. Si el IPC es negativo, no se permite ningún aumento.",
      "key_value": {
        "label": "maximum annual rent increase",
        "value": "min(3%, 80% of CPI)"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Residential real property with a certificate of occupancy issued after February 1, 1995 pursuant to Costa-Hawkins",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "certificate_of_occupancy_date",
                "operator": ">",
                "value": "1995-02-01"
              }
            ]
          }
        },
        {
          "description": "Housing restricted as deed-restricted affordable housing or subsidized affordable housing",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "rent_subsidized",
                "operator": "==",
                "value": true
              }
            ]
          }
        },
        {
          "description": "Dormitories owned and operated by an educational institution (higher ed or K-12)",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Housing issued a certificate of occupancy within the previous 15 years",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "building_age_years",
                "operator": "<",
                "value": 15
              }
            ]
          }
        },
        {
          "description": "Separately alienable residential property where owner is not a REIT, corporation, or corporate-member LLC, with required lease notice",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "in",
                "value": [
                  "single_family",
                  "condominium"
                ]
              },
              {
                "field": "owner_type",
                "operator": "not_in",
                "value": [
                  "reit",
                  "corporation"
                ]
              }
            ]
          }
        },
        {
          "description": "Two-unit property where owner occupied one unit at beginning of tenancy and continues occupancy, excluding ADU/JADU",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "duplex"
              },
              {
                "field": "units",
                "operator": "==",
                "value": 2
              },
              {
                "field": "owner_occupied",
                "operator": "==",
                "value": true
              }
            ]
          }
        },
        {
          "description": "Mobilehome space subject to long-term agreement exceeding one year, newly constructed mobilehome space offered on or after January 1, 1990, or mobilehome not used as primary residence",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "mobile_home"
              }
            ]
          }
        }
      ],
      "effective_date": "2022-10-18",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "yields_to",
        "target_scope": "state",
        "source_language": "unless expressly exempt under the Costa-Hawkins Rental Housing Act codified in California Civil Code section 1954.50, et seq., or the Mobilehome Residency Law codified in California Civil Code sections 798, et seq."
      },
      "penalty": "Rent increase is ineffective; complete affirmative defense in unlawful detainer; civil action for damages/injunction; administrative citation, infraction, or misdemeanor.",
      "source_citation": "Santa Ana Mun. Code § 8-3140(a)",
      "quote": {
        "chunk": "c347",
        "start_words": "Increases in Rent on Residential Real Property",
        "end_words": "notice or demand for a prohibited increase in Rent."
      },
      "confidence": 0.99
    }
  ]
}
